function (values, root, changed) {
  var TOTAL = 6;
  var MATCH = 4;
  var svg = root.querySelector(".v56");
  if (!svg) return;
  var turn = Math.max(1, Math.min(Math.round(Number(values.turn) || 1), TOTAL));
  var a = svg.querySelectorAll(".v56-a");
  var b = svg.querySelectorAll(".v56-b");
  var nums = svg.querySelectorAll(".v56-num");
  var read = svg.querySelector(".v56-read");
  var tally = svg.querySelector(".v56-tally");
  var i;
  for (i = 0; i < TOTAL; i += 1) {
    var on = i < turn;
    var ab = a[i];
    var bb = b[i];
    ab.style.transformOrigin = (Number(ab.getAttribute("x")) + Number(ab.getAttribute("width")) / 2) + "px 68px";
    ab.style.transform = "scaleY(" + (on ? 1 : 0) + ")";
    var isBody = (i + 1) === MATCH;
    if (isBody) bb.classList.toggle("v56-body", on);
    bb.style.transformOrigin = (Number(bb.getAttribute("x")) + Number(bb.getAttribute("width")) / 2) + "px 126px";
    bb.style.transform = "scaleY(" + (on ? (isBody ? 1 : 0.1) : 0) + ")";
  }
  for (i = 0; i < nums.length; i += 1) {
    nums[i].classList.toggle("v56-hot", i === turn - 1);
  }
  if (read) {
    read.textContent = turn === MATCH
      ? "Turn 4: this request is the skill's job."
      : "Turn " + turn + ": nothing here is the skill's job.";
  }
  if (tally) {
    tally.textContent = "AGENTS.md: " + turn + (turn === 1 ? " file" : " files") + ". The skill: "
      + turn + (turn === 1 ? " line" : " lines") + (turn >= MATCH ? " + 1 body." : ", no body yet.");
  }
}
